l="#fff"></rect><text x="44" y="54" class="sc-t sc-t-label">Fixed price</text><text x="44" y="92" class="sc-t sc-t-price">$149</text><text x="44" y="114" class="sc-t sc-t-field">Replace leaking pipe joint</text><rect x="44" y="128" width="196" height="30" rx="9" fill="#0f1a2a"></rect><text x="142" y="148" text-anchor="middle" class="sc-t sc-t-btn sc-approve">Approve price</text><g class="sc-approved"><text x="134" y="148" text-anchor="middle" class="sc-t sc-t-btn">Approved</text><path d="m172 142 3.5 3.5 7-7" stroke="#fff" stroke-width="2.4"></path></g></g></g><!-- chapter 6: done (same check geometry as the form's success state) --><g class="sc-done hide"><rect x="24" y="24" width="236" height="178" rx="18" fill="#fff"></rect><g transform="translate(40 38) scale(.6)"><circle class="sc-check-ring hide" pathLength="1" cx="40" cy="40" r="36" stroke="#12b76a" stroke-width="5"></circle><path class="sc-check-mark hide" pathLength="1" d="M25 41.5 35.5 52 56 30" stroke="#12b76a" stroke-width="6"></path></g><text x="100" y="62" class="sc-t sc-t-title">Leak fixed</text><text x="100" y="80" class="sc-t sc-t-field">12:50 am · floor dry</text><g class="sc-badge hide"><rect x="40" y="100" width="172" height="30" rx="15" fill="#fff1e8"></rect><path d="M58 106l7 3v5c0 4-3 7-7 8-4-1-7-4-7-8v-5z" stroke="var(--accent)" stroke-width="1.8"></path><text x="72" y="120" class="sc-t sc-t-badge">2-year guarantee</text></g><g transform="translate(52 164)"><path d="M0-9 2.6-3.2 9-2.8 4.1 1.3 5.6 7.6 0 4.2-5.6 7.6-4.1 1.3-9-2.8-2.6-3.2z" stroke="#e4e0d7" stroke-width="1.6"></path><path class="sc-star sc-star-1 hide" d="M0-9 2.6-3.2 9-2.8 4.1 1.3 5.6 7.6 0 4.2-5.6 7.6-4.1 1.3-9-2.8-2.6-3.2z" fill="#f59e0b" stroke="#f59e0b" stroke-width="1.6"></path></g><g transform="translate(80 164)"><path d="M0-9 2.6-3.2 9-2.8 4.1 1.3 5.6 7.6 0 4.2-5.6 7.6-4.1 1.3-9-2.8-2.6-3.2z" stroke="#e4e0d7" stroke-width="1.6"></path><path class="sc-star sc-star-2 hide" d="M0-9 2.6-3.2 9-2.8 4.1 1.3 5.6 7.6 0 4.2-5.6 7.